from pathlib import Path
import hashlib, json, re
from datetime import datetime, timezone
source = Path('products/services/uk-low-value-csv-buyer/raw/tender-feed.json')
raw = source.read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == 'a6d3f9b0dfbebd1cb1dd5b9bc98df9c666e04a1ca3c6edbf48dc7d3835fd6efa', 'Feed differs from the committed receipt'
package = json.loads(raw)
releases = package['releases']
pattern = re.compile(r'\bcsv\b|data migration|data quality|data validation|data cleansing|data cleaning|data reconciliation|data conversion|data mapping|data integrity|quality assurance', re.I)
rows = []
for release in releases:
    tender = release.get('tender') or {}
    fields = [('title', tender.get('title')), ('description', tender.get('description'))]
    for index, lot in enumerate(tender.get('lots') or []):
        fields.extend((f'lots[{index}].{key}', lot.get(key)) for key in ('title', 'description'))
    matches = []
    for field, value in fields:
        if isinstance(value, str):
            match = pattern.search(value)
            if match:
                matches.append({'field': field, 'excerpt': value[max(0, match.start()-100):match.end()+180]})
    if not matches:
        continue
    deadline = (tender.get('tenderPeriod') or {}).get('endDate')
    deadline_state = 'unverified'
    if isinstance(deadline, str):
        try:
            parsed = datetime.fromisoformat(deadline.replace('Z', '+00:00'))
            if parsed.tzinfo is not None:
                deadline_state = 'future' if parsed > datetime.now(timezone.utc) else 'elapsed'
        except ValueError:
            pass
    rows.append({'release_id': release.get('id'), 'ocid': release.get('ocid'), 'tags': release.get('tag'), 'title': tender.get('title'), 'status': tender.get('status'), 'feed_deadline': deadline, 'feed_deadline_state': deadline_state, 'matches': matches})
output = Path('products/services/uk-low-value-csv-buyer/director-feed-triage.json')
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps({'source': 'https://www.find-tender.service.gov.uk/api/1.0/ocdsReleasePackages?stages=tender&limit=25', 'source_sha256': digest, 'screened_at_utc': datetime.now(timezone.utc).isoformat(), 'releases_screened': len(releases), 'keyword_matches': rows, 'scope': 'One saved feed page screened on tender and lot titles and descriptions. Matches are pointers. No finding about bid fit, payment terms, or wider demand.'}, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(output), 'screened': len(releases), 'keyword_matches': len(rows)}))
